#!/usr/bin/env python3
"""Offline HTTP/3 -> HTTP/1.1 request bridge with a strict audit ledger.

Reads one JSON scenario from stdin, writes one JSON ledger to stdout.
No sockets, no child processes, no filesystem writes: only the standard
library is used and every operation happens in memory.
"""

import ipaddress
import json
import sys

MAX_SECTION_SIZE = 8192
MAX_BODY = 65536

METHODS = frozenset((b"GET", b"HEAD", b"POST", b"PUT", b"PATCH", b"DELETE", b"OPTIONS"))
SCHEMES = frozenset((b"http", b"https"))
DEFAULT_PORTS = {b"http": 80, b"https": 443}

PSEUDO_NAMES = frozenset((b":method", b":scheme", b":authority", b":path"))
PROHIBITED_NAMES = frozenset((
    b"connection", b"proxy-connection", b"keep-alive", b"transfer-encoding",
    b"upgrade", b"http2-settings", b"trailer",
))
REPEATABLE_NAMES = frozenset((
    b"accept", b"accept-encoding", b"cache-control", b"if-match",
    b"if-none-match", b"pragma", b"vary",
))

# Lowercase letters, digits and the RFC 9110 tchar punctuation subset.
TCHAR_PUNCT = frozenset(b"!#$%&'*+-.^_`|~")
HEX_DIGITS = frozenset(b"0123456789abcdefABCDEF")
PATH_PLAIN = frozenset(
    b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
    b"-._~!$&'()*+,;=:@/?"
)

TRAILER_PREFIX = b"x-audit-"
LIST_PREFIX = b"x-list-"


def octets(text):
    """Map a JSON string onto its octet string (U+0000..U+00FF per octet).

    Code points above U+00FF cannot denote an octet; they are folded onto a
    control octet that every field rule rejects.
    """
    if isinstance(text, bytes):
        return text
    out = bytearray()
    for ch in text:
        cp = ord(ch)
        out.append(cp if cp <= 0xFF else 0x01)
    return bytes(out)


def is_lower_tchar(byte):
    if 0x61 <= byte <= 0x7A:
        return True
    if 0x30 <= byte <= 0x39:
        return True
    return byte in TCHAR_PUNCT


def valid_regular_name(name):
    if not name:
        return False
    for byte in name:
        if not is_lower_tchar(byte):
            return False
    return True


def _value_edge_ok(byte):
    return (0x21 <= byte <= 0x7E) or (0x80 <= byte <= 0xFF)


def valid_field_value(value):
    if not value:
        return True
    if not _value_edge_ok(value[0]) or not _value_edge_ok(value[-1]):
        return False
    for byte in value[1:-1]:
        if not _value_edge_ok(byte) and byte not in (0x20, 0x09):
            return False
    return True


def valid_path(path):
    """Origin-form (or '*') path check; the path must not be decoded."""
    if path == b"*":
        return True
    if not path or path[0:1] != b"/":
        return False
    if path[0:2] == b"//":
        return False
    index = 0
    length = len(path)
    while index < length:
        byte = path[index]
        if byte == 0x25:  # '%'
            if index + 2 >= length:
                return False
            if path[index + 1] not in HEX_DIGITS or path[index + 2] not in HEX_DIGITS:
                return False
            index += 3
        elif byte in PATH_PLAIN:
            index += 1
        else:
            return False
    return True


def normalize_host(host):
    """Canonicalize a host portion; returns bytes or None."""
    if not host:
        return None
    labels = host.split(b".")
    if len(labels) == 4 and all(label and label.isdigit() for label in labels):
        parts = []
        for label in labels:
            if len(label) > 1 and label[0:1] == b"0":
                return None
            value = int(label)
            if value > 255:
                return None
            parts.append(str(value))
        return ".".join(parts).encode("ascii")
    if len(host) > 253:
        return None
    for label in labels:
        if not (1 <= len(label) <= 63):
            return None
        for byte in label:
            if not (48 <= byte <= 57 or 65 <= byte <= 90 or 97 <= byte <= 122 or byte == 0x2D):
                return None
        first = label[0]
        last = label[-1]
        if not (48 <= first <= 57 or 65 <= first <= 90 or 97 <= first <= 122):
            return None
        if not (48 <= last <= 57 or 65 <= last <= 90 or 97 <= last <= 122):
            return None
    return host.lower()


def parse_port(port):
    if not port or len(port) > 5:
        return None
    for byte in port:
        if not (48 <= byte <= 57):
            return None
    value = int(port)
    if value < 1 or value > 65535:
        return None
    return value


def canonical_authority(raw, scheme):
    """Canonical 'scheme://authority' host part; returns bytes or None."""
    if not raw:
        return None
    port = None
    if raw[0:1] == b"[":
        end = raw.find(b"]")
        if end < 0:
            return None
        inner = raw[1:end]
        rest = raw[end + 1:]
        if b"[" in inner or b"]" in inner or b"%" in inner:
            return None
        try:
            address = ipaddress.IPv6Address(inner.decode("ascii"))
        except (ValueError, UnicodeDecodeError):
            return None
        host = ("[" + address.compressed + "]").encode("ascii")
        if rest:
            if rest[0:1] != b":":
                return None
            port = parse_port(rest[1:])
            if port is None:
                return None
    else:
        if b"[" in raw or b"]" in raw:
            return None
        if raw.count(b":") > 1:
            return None
        if b":" in raw:
            host_raw, port_raw = raw.split(b":", 1)
        else:
            host_raw, port_raw = raw, b""
        host = normalize_host(host_raw)
        if host is None:
            return None
        if port_raw:
            port = parse_port(port_raw)
            if port is None:
                return None
    if port is not None and port != DEFAULT_PORTS[scheme]:
        host += b":" + str(port).encode("ascii")
    return host


def parse_content_length(values, body_length):
    """Every member of every line must denote the same integer as the body."""
    normalized = set()
    for value in values:
        for member in value.split(b","):
            member = member.strip(b" \t")
            if not member:
                return False
            for byte in member:
                if not (48 <= byte <= 57):
                    return False
            stripped = member.lstrip(b"0")
            normalized.add(stripped if stripped else b"0")
    if len(normalized) != 1:
        return False
    return normalized.pop() == str(body_length).encode("ascii")


def parse_section(fields):
    pairs = []
    for field in fields:
        name, value = field[0], field[1]
        pairs.append((octets(name), octets(value)))
    return pairs


def section_size(pairs):
    return sum(len(name) + len(value) + 32 for name, value in pairs)


def is_list_name(name):
    return name.startswith(LIST_PREFIX) and len(name) > len(LIST_PREFIX)


def evaluate(state, routes):
    """Validate one complete stream; returns a request dict or None."""
    kinds = state["kinds"]
    sections = state["sections"]
    body = bytes(state["body"])

    if len(body) > MAX_BODY:
        return None

    # Frame shape: one initial HEADERS, DATA*, optionally one trailing HEADERS.
    header_count = kinds.count("headers")
    if header_count == 1:
        if kinds[0] != "headers" or any(kind != "data" for kind in kinds[1:]):
            return None
        trailer_pairs = None
    elif header_count == 2:
        if kinds[0] != "headers" or kinds[-1] != "headers":
            return None
        if any(kind != "data" for kind in kinds[1:-1]):
            return None
        trailer_pairs = sections[1]
    else:
        return None

    initial = sections[0]
    if section_size(initial) > MAX_SECTION_SIZE:
        return None
    if trailer_pairs is not None and section_size(trailer_pairs) > MAX_SECTION_SIZE:
        return None

    pseudo = {}
    regular = []
    seen_regular = False
    for name, value in initial:
        if not valid_field_value(value):
            return None
        if name[0:1] == b":":
            if seen_regular:
                return None
            if name not in PSEUDO_NAMES:
                return None
            if name in pseudo:
                return None
            pseudo[name] = value
        else:
            seen_regular = True
            if not valid_regular_name(name):
                return None
            regular.append((name, value))

    for name in (b":method", b":scheme", b":path"):
        if name not in pseudo:
            return None

    method = pseudo[b":method"]
    scheme = pseudo[b":scheme"]
    path = pseudo[b":path"]

    if method not in METHODS:
        return None
    if scheme not in SCHEMES:
        return None
    if path == b"*":
        if method != b"OPTIONS":
            return None
    elif not valid_path(path):
        return None

    # Authority: either :authority or exactly one host field.
    host_values = [value for name, value in regular if name == b"host"]
    authority = pseudo.get(b":authority")
    if authority is None and not host_values:
        return None
    if len(host_values) > 1:
        return None
    if authority is not None and host_values:
        if authority != host_values[0]:
            return None
    raw_authority = authority if authority is not None else host_values[0]
    if not raw_authority:
        return None
    authority_bytes = canonical_authority(raw_authority, scheme)
    if authority_bytes is None:
        return None

    # Regular field policy.
    counts = {}
    for name, _ in regular:
        counts[name] = counts.get(name, 0) + 1

    for name in counts:
        if name in PROHIBITED_NAMES:
            return None

    te_values = [value for name, value in regular if name == b"te"]
    if len(te_values) > 1:
        return None
    if te_values and te_values[0] != b"trailers":
        return None

    content_lengths = [value for name, value in regular if name == b"content-length"]
    if content_lengths and not parse_content_length(content_lengths, len(body)):
        return None

    for name, count in counts.items():
        if name in (b"host", b"te", b"content-length", b"cookie"):
            continue
        if count > 1:
            if name in REPEATABLE_NAMES or is_list_name(name):
                continue
            return None

    # Trailers.
    trailers = []
    if trailer_pairs is not None:
        for name, value in trailer_pairs:
            if not valid_field_value(value):
                return None
            if not valid_regular_name(name):
                return None
            if not name.startswith(TRAILER_PREFIX) or len(name) <= len(TRAILER_PREFIX):
                return None
            trailers.append((name, value))

    # Route lookup.
    route_key = scheme.decode("ascii") + "://" + authority_bytes.decode("ascii")
    origin = routes.get(route_key)
    if origin is None:
        return None

    # Emitted regular fields: occurrence order, host/content-length/te removed,
    # cookie lines merged into one line at the first cookie position.
    cookie_values = [value for name, value in regular if name == b"cookie"]
    joined_cookie = b"; ".join(cookie_values) if cookie_values else None
    emitted = []
    cookie_done = False
    for name, value in regular:
        if name in (b"host", b"content-length", b"te"):
            continue
        if name == b"cookie":
            if cookie_done:
                continue
            cookie_done = True
            emitted.append((name, joined_cookie))
            continue
        emitted.append((name, value))

    raw = bytearray()
    raw += method + b" " + path + b" HTTP/1.1\r\n"
    raw += b"host: " + authority_bytes + b"\r\n"
    for name, value in emitted:
        raw += name + b": " + value + b"\r\n"
    if trailers is None:
        raw += b"content-length: " + str(len(body)).encode("ascii") + b"\r\n"
        raw += b"\r\n"
        raw += body
    else:
        raw += b"transfer-encoding: chunked\r\n"
        if trailers:
            names = []
            for name, _ in trailers:
                if name not in names:
                    names.append(name)
            raw += b"trailer: " + b", ".join(names) + b"\r\n"
        raw += b"\r\n"
        if body:
            raw += format(len(body), "x").encode("ascii") + b"\r\n"
            raw += body
            raw += b"\r\n"
        raw += b"0\r\n"
        for name, value in trailers:
            raw += name + b": " + value + b"\r\n"
        raw += b"\r\n"

    return {
        "origin": origin,
        "raw": bytes(raw),
        "cache_key": [
            method.decode("ascii"),
            scheme.decode("ascii"),
            authority_bytes.decode("ascii"),
            path.decode("ascii"),
        ],
    }


def blank_record(sid, status):
    return {
        "sid": sid,
        "status": status,
        "commit_at": None,
        "origin": None,
        "offset": None,
        "length": 0,
        "cache_key": None,
    }


def bridge(scenario):
    routes = scenario.get("routes") or {}
    events = scenario.get("events") or []

    pipelines = {}
    for label in routes.values():
        pipelines.setdefault(label, bytearray())

    states = {}
    records = {}

    for index, event in enumerate(events):
        sid = event["sid"]
        state = states.get(sid)
        if state is None:
            state = states[sid] = {
                "kinds": [],
                "sections": [],
                "body": bytearray(),
                "terminal": None,
            }
        kind = event.get("type")
        if kind == "headers":
            state["kinds"].append("headers")
            state["sections"].append(parse_section(event.get("fields") or []))
        elif kind == "data":
            state["kinds"].append("data")
            state["body"].extend(bytes.fromhex(event.get("hex") or ""))
        elif kind == "unknown":
            pass
        elif kind == "fin":
            state["terminal"] = ("fin", index)
        elif kind == "reset":
            state["terminal"] = ("reset", index)

    for sid in sorted(states):
        state = states[sid]
        terminal = state["terminal"]
        if terminal is None:
            records[sid] = blank_record(sid, "incomplete")
            continue
        kind, index = terminal
        if kind == "reset":
            records[sid] = blank_record(sid, "cancelled")
            continue
        request = evaluate(state, routes)
        if request is None:
            records[sid] = blank_record(sid, "rejected")
            continue
        origin = request["origin"]
        pipeline = pipelines.setdefault(origin, bytearray())
        offset = len(pipeline)
        raw = request["raw"]
        pipeline.extend(raw)
        records[sid] = {
            "sid": sid,
            "status": "forwarded",
            "commit_at": index,
            "origin": origin,
            "offset": offset,
            "length": len(raw),
            "cache_key": request["cache_key"],
        }

    return {
        "streams": [records[sid] for sid in sorted(records)],
        "origins": {label: bytes(raw).hex() for label, raw in pipelines.items()},
    }


def main():
    data = sys.stdin.buffer.read()
    scenario = json.loads(data.decode("utf-8"))
    result = bridge(scenario)
    out = json.dumps(result, ensure_ascii=True)
    sys.stdout.write(out)
    sys.stdout.write("\n")
    sys.stdout.flush()


if __name__ == "__main__":
    main()
